SELECT * FROM `${slotTable}`

    AND item_id=#{itemId}
    AND DATE(start_at)=#{day}

ORDER BY start_at, id

mapper.insert:
INSERT INTO `${resvTable}` (
    slot_id, username, status, remark


            `${col}`


    , created_at
) VALUES (
    #{slotId}, #{username}, #{status}, #{remark}


            #{val}


    , #{createdAt}
)

mapper.select:
SELECT * FROM `${resvTable}`

    AND username=#{username}
    AND status=#{status}

ORDER BY id DESC
